-- Lastro: estrutura do banco de dados
-- Rode este arquivo inteiro no Supabase: SQL Editor > New query > colar > Run

create table if not exists public.projetos (
  id text primary key,
  dados jsonb not null,
  atualizado_em timestamptz not null default now()
);

alter table public.projetos enable row level security;

-- Modo demonstração: qualquer visitante do site lê, cria e edita projetos
-- (não há exclusão pelo site). Para restringir a membros logados, troque "anon, authenticated" por "authenticated".
drop policy if exists "visitantes leem" on public.projetos;
drop policy if exists "visitantes criam" on public.projetos;
drop policy if exists "visitantes editam" on public.projetos;
create policy "visitantes leem" on public.projetos for select to anon, authenticated using (true);
create policy "visitantes criam" on public.projetos for insert to anon, authenticated with check (true);
create policy "visitantes editam" on public.projetos for update to anon, authenticated using (true) with check (true);

